"""Migrated order_fulfilment workflow."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _numeric_value(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal("0")


def _account_credit_hold(record: dict, tables: dict) -> Any:
    if "ACCT_ID" not in record:
        return ""

    account_id = record["ACCT_ID"]
    for row in tables.get("ACCT_MASTER", []) or []:
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG") == "Y":
            continue
        if row.get("ACCT_ID") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    new_record = dict(record)
    audits: list[str] = []
    notifies: list[str] = []

    target_state = state
    matched = False

    if state == "E" and event == "approve":
        if _numeric_value(record.get("TOT_AMT")) > 0:
            target_state = "A"
            audits.append("ORD_APPR")
            matched = True

    elif state == "A" and event == "ship":
        target_state = "S"
        audits.append("ORD_SHIP")
        notifies.append("shipped")
        matched = True

    elif state == "S" and event == "invoice":
        target_state = "I"
        audits.append("ORD_INV")
        matched = True

    elif state == "E" and event == "cancel":
        target_state = "X"
        audits.append("ORD_CANC")
        matched = True

    elif state == "A" and event == "cancel":
        if _account_credit_hold(record, tables) != "Y":
            target_state = "X"
            audits.append("ORD_CANC")
            matched = True

    elif state == "I" and event == "cancel":
        target_state = "X"
        audits.append("ORD_CANC_INV")
        notifies.append("credit_note")
        matched = True

    if not matched:
        audits = ["WF_NOMATCH"]

    return {
        "state": target_state,
        "record": new_record,
        "audits": audits,
        "notifies": notifies,
        "matched": matched,
    }
